import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  DOCTOR = 'DOCTOR',
  PATIENT = 'PATIENT'
}

export interface AnalysisResult {
  title: string;
  content: string;
  type: 'text' | 'image-analysis' | 'error';
  sources?: Array<{ web?: { uri: string; title: string } }>;
}

export interface MedicalReport {
  id: string;
  type: 'ECG' | 'XRAY' | 'LAB' | 'MRI';
  imageUrl: string;
  timestamp: Date;
}

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { AnalysisResult } from "../types";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

export const analyzeMedicalImage = async (
  base64Data: string, 
  reportType: string
): Promise<AnalysisResult> => {
  const ai = getAIClient();
  const prompt = `You are a world-class senior medical diagnostic assistant. Analyze this ${reportType} report/image. 
  Provide a detailed clinical summary including:
  1. Key Observations
  2. Potential Clinical Implications
  3. Suggested Next Steps
  Keep it professional, concise, and structured. Disclaimer: This is an AI-generated analysis for educational purposes.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: 'image/jpeg' } },
          { text: prompt }
        ]
      }
    });

    return {
      title: `${reportType} Analysis`,
      content: response.text || "Unable to process the image.",
      type: 'image-analysis'
    };
  } catch (error) {
    console.error("AI Analysis Error:", error);
    return {
      title: "Analysis Failed",
      content: "An error occurred while communicating with the AI. Please try again.",
      type: 'error'
    };
  }
};

export const searchMedicalQueries = async (query: string): Promise<AnalysisResult> => {
  const ai = getAIClient();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: query,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });

    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    return {
      title: "AI Medical Search",
      content: response.text || "No results found.",
      type: 'text',
      sources: sources as any
    };
  } catch (error) {
    return {
      title: "Search Error",
      content: "Could not fetch medical data. Check your connection.",
      type: 'error'
    };
  }
};

export const auditMedicalBill = async (base64Data: string): Promise<AnalysisResult> => {
  const ai = getAIClient();
  const prompt = `Review this medical bill/invoice. 
  1. Identify the services charged.
  2. Check for potential excessive charges or common billing errors.
  3. Suggest if prices seem fair based on general medical standards.
  4. Look for hidden charges or duplicate entries.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType: 'image/jpeg' } },
          { text: prompt }
        ]
      }
    });

    return {
      title: "Bill Audit Result",
      content: response.text || "Unable to audit the bill.",
      type: 'image-analysis'
    };
  } catch (error) {
    return {
      title: "Audit Error",
      content: "Failed to process the bill. Please try again.",
      type: 'error'
    };
  }
};

import React from 'react';
import { X, ExternalLink, ShieldAlert, Sparkles } from 'lucide-react';
import { AnalysisResult } from '../types';

interface AIModalProps {
  result: AnalysisResult | null;
  isOpen: boolean;
  onClose: () => void;
  isLoading?: boolean;
}

const AIModal: React.FC<AIModalProps> = ({ result, isOpen, onClose, isLoading }) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
      <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl flex flex-col max-h-[85vh] overflow-hidden">
        <div className="flex justify-between items-center p-6 border-b border-slate-100">
          <div className="flex items-center gap-2">
            <div className="p-2 bg-blue-100 rounded-lg">
              <Sparkles className="text-blue-600 w-5 h-5" />
            </div>
            <h3 className="font-bold text-slate-800 text-lg">
              {isLoading ? "AI Thinking..." : result?.title}
            </h3>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
            <X className="w-6 h-6 text-slate-400" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 scrollbar-hide">
          {isLoading ? (
            <div className="flex flex-col items-center justify-center py-12">
              <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-4"></div>
              <p className="text-slate-500 animate-pulse">Analyzing clinical data...</p>
            </div>
          ) : (
            <>
              <div className="prose prose-slate max-w-none">
                <div className="whitespace-pre-wrap text-slate-700 leading-relaxed text-sm">
                  {result?.content}
                </div>
              </div>

              {result?.sources && result.sources.length > 0 && (
                <div className="mt-8 border-t pt-4">
                  <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Verified Sources</h4>
                  <div className="space-y-2">
                    {result.sources.map((s, idx) => s.web && (
                      <a 
                        key={idx}
                        href={s.web.uri}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center justify-between p-3 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors group"
                      >
                        <span className="text-xs font-medium text-slate-600 truncate mr-2">{s.web.title || s.web.uri}</span>
                        <ExternalLink className="w-3 h-3 text-slate-400 group-hover:text-blue-600" />
                      </a>
                    ))}
                  </div>
                </div>
              )}

              <div className="mt-6 p-3 bg-amber-50 rounded-xl border border-amber-100 flex gap-2">
                <ShieldAlert className="w-5 h-5 text-amber-600 shrink-0" />
                <p className="text-[10px] text-amber-800">
                  Disclaimer: This AI analysis is for supportive purposes only and should not replace professional medical advice. Always consult with a certified healthcare provider.
                </p>
              </div>
            </>
          )}
        </div>

        <div className="p-4 border-t border-slate-100 flex justify-end">
          <button 
            onClick={onClose}
            className="px-6 py-2 bg-slate-800 text-white rounded-xl font-bold text-sm hover:bg-slate-900 transition-colors shadow-md"
          >
            Done
          </button>
        </div>
      </div>
    </div>
  );
};

export default AIModal;

import React, { useState, useCallback } from 'react';
import { 
  Bell, User, Search, Mic, Activity, FileText, Brain, 
  Stethoscope, MapPin, Star, Upload, ShieldCheck, 
