  HeartPulse, Zap, Home, Menu, Phone, Sparkles, PlusCircle, CreditCard
} from 'lucide-react';
import { UserRole, AnalysisResult, PrescriptionData } from './types';
import { analyzeMedicalImage, searchMedicalQueries, auditMedicalBill } from './services/geminiService';
import AIModal from './components/AIModal';
import PrescriptionForm from './components/PrescriptionForm';
import PaymentModal from './components/PaymentModal';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.DOCTOR);
  const [currentView, setCurrentView] = useState<'HOME' | 'PRESCRIPTION'>('HOME');
  const [searchQuery, setSearchQuery] = useState('');
  const [isAIModalOpen, setIsAIModalOpen] = useState(false);
  const [aiResult, setAiResult] = useState<AnalysisResult | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Payment States
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [pendingBillAmount, setPendingBillAmount] = useState<string>('0.00');

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: string) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsAiLoading(true);
    setIsAIModalOpen(true);

    try {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64Data = (reader.result as string).split(',')[1];
        let result: AnalysisResult;

        if (type === 'BILL') {
          result = await auditMedicalBill(base64Data);
          // For demo purposes, if it's a bill, we set a mock amount
          setPendingBillAmount((Math.random() * 500 + 50).toFixed(2));
        } else {
          result = await analyzeMedicalImage(base64Data, type);
        }

        setAiResult(result);
        setIsAiLoading(false);
      };
      reader.readAsDataURL(file);
    } catch (err) {
      setAiResult({ title: "Error", content: "Failed to read file.", type: 'error' });
      setIsAiLoading(false);
    }
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;

    setIsAiLoading(true);
    setIsAIModalOpen(true);
    const result = await searchMedicalQueries(searchQuery);
    setAiResult(result);
    setIsAiLoading(false);
