    switch(status) {
      case 'Confirmed': return 'text-green-600 bg-green-50';
      case 'Pending': return 'text-amber-600 bg-amber-50';
      case 'Completed': return 'text-blue-600 bg-blue-50';
      default: return 'text-slate-600 bg-slate-50';
