            <div className="flex flex-col items-center gap-1 text-slate-400 hover:text-slate-600 transition-colors group cursor-pointer">
               <User size={26} className="transition-transform group-hover:-translate-y-0.5"/>
               <span className="text-[9px] font-bold uppercase tracking-widest">Profile</span>
            </div>
            <div className="flex flex-col items-center gap-1 text-slate-400 hover:text-slate-600 transition-colors group cursor-pointer">
               <Menu size={26} className="transition-transform group-hover:-translate-y-0.5"/>
               <span className="text-[9px] font-bold uppercase tracking-widest">Menu</span>
            </div>
        </nav>

        {/* AI Processing Modal */}
        <AIModal 
          isOpen={isAIModalOpen} 
          result={aiResult} 
          isLoading={isAiLoading} 
          onClose={() => {
            setIsAIModalOpen(false);
            setAiResult(null);
          }} 
        />

        {/* Payment Modal */}
        <PaymentModal 
          isOpen={isPaymentModalOpen}
          amount={pendingBillAmount}
          onClose={() => setIsPaymentModalOpen(false)}
          onSuccess={() => setIsPaymentModalOpen(false)}
        />
      </div>
    </div>
  );
};

