          result = await analyzeRetinaImage(base64Data);
        } else {
          result = await analyzeMedicalImage(base64Data, type, fileMimeType);
        }

        setAiResult(result);
        setIsAiLoading(false);
      };
      reader.readAsDataURL(file);
