  HeartPulse, Zap, Home, Menu, Phone, Sparkles, PlusCircle, CreditCard, Calendar, Pill,
  UserPlus, TrendingUp, Eye, Receipt, ChevronRight, X
} from 'lucide-react';
import { UserRole, AnalysisResult, PrescriptionData } from './types';
import { analyzeMedicalImage, searchMedicalQueries, auditMedicalBill, analyzeDermatologyImage, analyzeRetinaImage } from './services/geminiService';
import AIModal from './components/AIModal';
import PrescriptionForm from './components/PrescriptionForm';
import PaymentModal from './components/PaymentModal';
import Scheduler from './components/Scheduler';
import DrugInfo from './components/DrugInfo';
import GrowthHub from './components/GrowthHub';
