import DiagnosticsHub from './components/DiagnosticsHub';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.DOCTOR);
  const [currentView, setCurrentView] = useState<'HOME' | 'PRESCRIPTION' | 'SCHEDULE' | 'DRUG_INFO' | 'GROWTH' | 'BILLING' | 'DIAGNOSTICS'>('HOME');
  const [searchQuery, setSearchQuery] = useState('');
  const [isAIModalOpen, setIsAIModalOpen] = useState(false);
  const [aiResult, setAiResult] = useState<AnalysisResult | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  // Payment States
  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [pendingBillAmount, setPendingBillAmount] = useState<string>('0.00');

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: string) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const fileMimeType = file.type || 'image/jpeg';
    setIsAiLoading(true);
    setIsAIModalOpen(true);
    setIsMenuOpen(false); // Close menu if it was open

    try {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64Data = (reader.result as string).split(',')[1];
        let result: AnalysisResult;

        if (type === 'BILL') {
          result = await auditMedicalBill(base64Data);
          setPendingBillAmount((Math.random() * 500 + 50).toFixed(2));
        } else if (type === 'DERMA') {
          result = await analyzeDermatologyImage(base64Data);
        } else if (type === 'RETINA') {
          result = await analyzeRetinaImage(base64Data);
        } else {
          result = await analyzeMedicalImage(base64Data, type, fileMimeType);
        }

        setAiResult(result);
        setIsAiLoading(false);
      };
      reader.readAsDataURL(file);
    } catch (err) {
      setAiResult({ title: "Error", content: "Failed to read file.", type: 'error' });
      setIsAiLoading(false);
    }
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;

    setIsAiLoading(true);
    setIsAIModalOpen(true);
    const result = await searchMedicalQueries(searchQuery);
    setAiResult(result);
    setIsAiLoading(false);
  };

  const savePrescription = (data: PrescriptionData) => {
    console.log("Prescription Saved:", data);
    alert(`Prescription for ${data.patientName} saved to EHR!`);
    setCurrentView('HOME');
  };

  const MenuDropdown = () => (
    <div className={`fixed inset-0 z-[60] transition-all duration-500 ${isMenuOpen ? 'visible' : 'invisible pointer-events-none'}`}>
      <div className={`absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity duration-500 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)}></div>
      <div className={`absolute bottom-0 w-full max-w-md bg-white rounded-t-[3rem] shadow-2xl p-8 transform transition-transform duration-500 ease-out ${isMenuOpen ? 'translate-y-0' : 'translate-y-full'}`}>
        <div className="flex justify-between items-center mb-8">
