      reader.onloadend = async () => {
        const base64Data = (reader.result as string).split(',')[1];
        let result: AnalysisResult;

        if (type === 'BILL') {
          result = await auditMedicalBill(base64Data);
          setPendingBillAmount((Math.random() * 500 + 50).toFixed(2));
