            <div className="w-9 h-9 bg-slate-200 rounded-full overflow-hidden border-2 border-white shadow-sm"><img src={`https://picsum.photos/seed/${role}/100/100`} alt="Profile" className="w-full h-full object-cover" /></div>
          </div>
